-- Geo Follow-Up setup: a "Lost reason" Choice field on the space's field setup; cards show Date Quoted; 48-hour follow-up reminders on Initial and Second follow up; moving to Lost asks for the reason. Safe to run more than once.
update wf_templates t set fields = coalesce(t.fields,'[]'::jsonb) || jsonb_build_array(jsonb_build_object('id','flostrsn','name','Lost reason','type','choice','options',jsonb_build_array('Price','Went with another supplier','Lead time','Contractor didn''t win the job','Project cancelled or postponed','Spec''d a product we don''t carry','Other'))) where t.id::text = (select coalesce(nullif(s.field_set,''),(select x.id::text from wf_templates x where x.kind='fields' order by x.created_at limit 1)) from wf_spaces s where s.key='GF' and s.division_id in (select id::text from divisions where lower(name)='geo') limit 1) and not exists (select 1 from jsonb_array_elements(coalesce(t.fields,'[]'::jsonb)) f where lower(f->>'name')='lost reason') returning name;
update wf_spaces s set rules = (select coalesce(jsonb_agg(r),'[]'::jsonb) from jsonb_array_elements(s.rules) r where coalesce(r->>'kind','') not in ('remind','card') and not (r->>'kind'='fill' and r->>'value'='@ask')) || jsonb_build_array(jsonb_build_object('id','card','kind','card','field',(select f->>'id' from wf_templates t cross join jsonb_array_elements(coalesce(t.fields,'[]'::jsonb)) f where t.id::text=coalesce(nullif(s.field_set,''),(select x.id::text from wf_templates x where x.kind='fields' order by x.created_at limit 1)) and lower(f->>'name')='date quoted' limit 1)), jsonb_build_object('id','rfu1','kind','remind','status',(select st->>'name' from jsonb_array_elements(s.statuses) st where st->>'name' ilike 'init%' limit 1),'hours',48,'since',(extract(epoch from now())*1000)::bigint), jsonb_build_object('id','rfu2','kind','remind','status',(select st->>'name' from jsonb_array_elements(s.statuses) st where st->>'name' ilike 'second%' limit 1),'hours',48,'since',(extract(epoch from now())*1000)::bigint), jsonb_build_object('id','rlost','kind','fill','status',(select st->>'name' from jsonb_array_elements(s.statuses) st where st->>'name' ilike 'lost' limit 1),'field','cf:'||(select f->>'id' from wf_templates t cross join jsonb_array_elements(coalesce(t.fields,'[]'::jsonb)) f where t.id::text=coalesce(nullif(s.field_set,''),(select x.id::text from wf_templates x where x.kind='fields' order by x.created_at limit 1)) and lower(f->>'name')='lost reason' limit 1),'value','@ask','blank',false,'must',true)) where s.key='GF' and s.division_id in (select id::text from divisions where lower(name)='geo') returning name, rules;
